WITH with_windows AS (SELECT id, order_id, STDDEV_SAMP(quantity) OVER w_hist AS product_id_stddev_samp_quantity, SUM(unit_price) OVER (PARTITION BY product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_unit_price FROM order_items WINDOW w_hist AS (PARTITION BY product_id)), remaining_keys AS (SELECT order_id, id FROM with_windows EXCEPT ALL SELECT order_id, id FROM order_items WHERE unit_price < 170), kept_rows AS (SELECT s.* FROM with_windows s INNER JOIN remaining_keys k ON s.order_id = k.order_id AND s.id = k.id), with_windows_order_items AS (SELECT *, DENSE_RANK() OVER (ORDER BY running_unit_price NULLS FIRST) AS running_unit_price_dense_rank, STDDEV_SAMP(running_unit_price) OVER (PARTITION BY order_id) AS order_id_stddev_samp_running_unit_price, ROUND(running_unit_price / SUM(running_unit_price) OVER (PARTITION BY order_id), 4) AS running_unit_price_share FROM kept_rows WHERE product_id_stddev_samp_quantity BETWEEN 6 AND 8), valid AS (SELECT *, running_unit_price_share - running_unit_price_dense_rank AS running_unit_price_share_minus_running_unit_price_dense_rank, running_unit_price - product_id_stddev_samp_quantity AS running_unit_price_minus_product_id_stddev_samp_quantity FROM with_windows_order_items WHERE product_id_stddev_samp_quantity != 3), matched_keys AS (SELECT order_id FROM valid EXCEPT ALL SELECT order_id FROM order_items WHERE quantity = 6), verified AS (SELECT s.* FROM valid s INNER JOIN matched_keys k ON s.order_id = k.order_id) SELECT CASE WHEN running_unit_price_share_minus_running_unit_price_dense_rank >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END AS running_unit_price_share_minus_running_unit_price_dense_rank_tier, PERCENTILE_APPROX(running_unit_price_dense_rank, ARRAY(0.25, 0.5, 0.75)) AS running_unit_price_dense_rank_quartiles, PERCENTILE_APPROX(product_id_stddev_samp_quantity, 0.95) AS product_id_stddev_samp_quantity_p95, PERCENTILE_APPROX(product_id_stddev_samp_quantity, 0.95) AS product_id_stddev_samp_quantity_p95_2, COUNT(DISTINCT order_id) AS distinct_order_ids, PERCENTILE_APPROX(product_id_stddev_samp_quantity, 0.5) AS product_id_stddev_samp_quantity_p50, COUNT(DISTINCT order_id) AS distinct_order_ids_2 FROM verified GROUP BY CASE WHEN running_unit_price_share_minus_running_unit_price_dense_rank >= 79 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY product_id_stddev_samp_quantity_p50 DESC NULLS LAST;
